ok = bad = 0
for slug, items in DATA.items():
    d = os.path.join(MUSIC, 'Menus', FOLDER[slug]); os.makedirs(d, exist_ok=True)
    for name, tok in items:
        if not tok: print('no link', name); continue
        host, t = tok.split('|'); dst = os.path.join(d, name.replace('"', ''))
        if os.path.exists(dst): continue
        url = 'https://%s/soundtracks/%s/%s/%s' % (host, slug, t, urllib.parse.quote(name))
        try:
            data = urllib.request.urlopen(urllib.request.Request(url, headers=H), timeout=120).read()
            open(dst, 'wb').write(data); ok += 1; print('saved', FOLDER[slug], '-', name, len(data) >> 10, 'KB')
        except Exception as e: bad += 1; print('FAILED', name, e)
print('done:', ok, 'saved,', bad, 'failed')
